            modelBuilder.Entity("Wayni.Deudores.Infrastructure.Persistence.Entities.ImportJob", b =>
                {
                    b.Property<Guid>("Id")
                        .HasColumnType("char(36)")
                        .HasColumnName("id");

                    b.Property<string>("Bucket")
                        .IsRequired()
                        .HasMaxLength(63)
                        .HasColumnType("varchar(63)")
                        .HasColumnName("bucket");

                    b.Property<DateTime>("CreatedAt")
                        .HasColumnType("datetime(6)")
                        .HasColumnName("created_at");

                    b.Property<int>("Deudores")
                        .HasColumnType("int")
                        .HasColumnName("deudores");

                    b.Property<long?>("DuracionMs")
                        .HasColumnType("bigint")
                        .HasColumnName("duracion_ms");

                    b.Property<int>("Entidades")
                        .HasColumnType("int")
                        .HasColumnName("entidades");

                    b.Property<string>("Error")
                        .HasMaxLength(2000)
                        .HasColumnType("varchar(2000)")
                        .HasColumnName("error");

                    b.Property<string>("FileName")
                        .IsRequired()
                        .HasMaxLength(255)
                        .HasColumnType("varchar(255)")
                        .HasColumnName("file_name");

                    b.Property<DateTime?>("FinishedAt")
                        .HasColumnType("datetime(6)")
                        .HasColumnName("finished_at");

                    b.Property<long>("LineasInvalidas")
                        .HasColumnType("bigint")
                        .HasColumnName("lineas_invalidas");

                    b.Property<long>("LineasLeidas")
                        .HasColumnType("bigint")
                        .HasColumnName("lineas_leidas");

                    b.Property<string>("ObjectKey")
                        .IsRequired()
                        .HasMaxLength(512)
                        .HasColumnType("varchar(512)")
                        .HasColumnName("object_key");

                    b.Property<int?>("Periodo")
                        .HasColumnType("int")
